import{_ as a,o as n,a as p,b as l}from"./app.C41L12d5.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMT API","link":"/api/SIMT-API/SIMT-API"},{"text":"SIMT编程简介","link":"/api/SIMT-API/SIMT_programming_intro/SIMT_programming_intro"},{"text":"扩展语法","link":"/api/SIMT-API/SIMT_programming_intro/extended_syntax/extended_syntax"},{"text":"核函数（Kernel）配置","link":"/api/SIMT-API/SIMT_programming_intro/extended_syntax/kernel_function_config"}]},"headers":[],"relativePath":"api/SIMT-API/SIMT_programming_intro/extended_syntax/kernel_function_config.md","filePath":"api/SIMT-API/SIMT_programming_intro/extended_syntax/kernel_function_config.md","outlineHeaders":[{"level":2,"title":"核函数（Kernel）定义","slug":"核函数（Kernel）定义","link":"#核函数（Kernel）定义"},{"level":2,"title":"__launch_bounds__(N)","slug":"__launch_bounds__(N)","link":"#__launch_bounds__(N)"},{"level":2,"title":"<<<>>>调用","slug":"<<<>>>调用","link":"#<<<>>>调用"}],"lastUpdated":1787813964000}'),t={name:"api/SIMT-API/SIMT_programming_intro/extended_syntax/kernel_function_config.md"};function e(c,s,_,i,o,d){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>核函数（Kernel）配置</h1><h2 id="核函数（Kernel）定义">核函数（Kernel）定义<a class="header-anchor" href="#核函数（Kernel）定义">​</a></h2><p>核函数（Kernel）是SIMT编程的Device侧入口函数，负责协调整个算子的执行流程。函数定义语法为：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">kernel_name</span><span class="p">(</span><span class="kt">uint32_t</span><span class="o">*</span><span class="w"> </span><span class="n">param1</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">param2</span><span class="p">,</span><span class="w"> </span><span class="p">...);</span>
</code></pre></div><p>关键修饰符说明如下：</p><ul><li><code>__global__</code>：必需修饰符，作用为标识核函数（Kernel），表明可在Host侧通过&lt;&lt;&lt;...&gt;&gt;&gt;调用。</li></ul><p>核函数（Kernel）定义有以下几个约束：</p><ul><li>返回值类型必须是void；</li><li>入参支持基础数据类型和基础数据类型的指针类型，如int32_t、float、int32_t*、float*等。</li><li>指针参数必须是指向Global Memory上的内存地址。</li></ul><h2 id="__launch_bounds__(N)">__launch_bounds__(N)<a class="header-anchor" href="#__launch_bounds__(N)">​</a></h2><p>在多线程并发执行时，每个线程使用较少的寄存器可以让单个线程块内启动更多的线程，从而提升性能。因此，编译器会采用启发式算法，将寄存器溢出（register spilling）和指令数量控制在最低水平，同时尽量减少寄存器的使用量。应用程序可以通过在<code>__global__</code>函数定义中使用<code>__launch_bounds__()</code>限定符来限制启动边界（launch bounds），提供附加信息辅助编译器优化这一过程，这属于可选配置。</p><p><code>__launch_bounds__()</code>：函数标记宏，在核函数（Kernel）上可选配置，用于在编译期指定核函数（Kernel）启动的最大线程数。若未配置<code>__launch_bounds__</code>，最大线程数默认为1024。参数N需要满足：</p><ul><li><p>N &gt;= blockDim.x * blockDim.y *blockDim.z</p></li><li><p>N的取值范围为1到2048。</p><p>最大线程数决定了每个线程可分配到的寄存器数量，具体对应关系请见下表，寄存器用于存储线程中的局部变量，若局部变量的个数超出寄存器个数，容易出现寄存器溢出等问题。建议最大线程数与核函数（Kernel）启动时配置的线程数保持一致。</p><p><strong>表1</strong> __launch_bounds__(N)与每个线程可用的寄存器个数的关系</p><table><thead><tr><th>N</th><th>每个线程可用寄存器个数</th></tr></thead><tbody><tr><td>1025~2048</td><td>16</td></tr><tr><td>513~1024</td><td>32</td></tr><tr><td>257~512</td><td>64</td></tr><tr><td>1~256</td><td>127</td></tr></tbody></table></li></ul><h2 id="&lt;&lt;&lt;&gt;&gt;&gt;调用">&lt;&lt;&lt;&gt;&gt;&gt;调用<a class="header-anchor" href="#&lt;&lt;&lt;&gt;&gt;&gt;调用">​</a></h2><p>在SIMT编程下使用&lt;&lt;&lt;&gt;&gt;&gt;调用<code>__global__</code>限定符修饰的函数时必须指定执行配置，形如：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="o">&lt;&lt;&lt;</span><span class="n">blocks_per_grid</span><span class="p">,</span><span class="w"> </span><span class="n">threads_per_block</span><span class="p">,</span><span class="w"> </span><span class="n">dyn_ubuf_size</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span>
</code></pre></div><p>执行配置由4个参数决定，详细用法说明参考<a href="../../../../guide/programming_guide/language_extension/simt_builtin_keywords.html#%E6%A0%B8%E5%87%BD%E6%95%B0%E9%85%8D%E7%BD%AE">核函数（Kernel）配置</a>：</p><ul><li>blocks_per_grid：<a href="./builtin_data_types.html#dim3">dim3</a>类型，用于指定网格（grid）的维度与规模，blocks_per_grid.x * blocks_per_grid.y * blocks_per_grid.z等于启动的线程块总数，且不能超过65535。</li><li>threads_per_block：<a href="./builtin_data_types.html#dim3">dim3</a>类型，用于指定每个线程块（block）的维度与规模，threads_per_block.x * threads_per_block.y * threads_per_block.z等于每个线程块包含的线程数，需要小于等于__launch_bounds__配置。</li><li>dyn_ubuf_size：size_t类型，用于指定每个线程块动态分配的共享内存大小，单位为字节。这部分内存供数组使用，具体用法请参考<a href="../../../../guide/programming_guide/programming_model/ai_core_simt_programming/memory_hierarchy.html#%E5%85%B1%E4%BA%AB%E5%86%85%E5%AD%98">共享内存</a>中的“动态申请”方式。</li><li>stream：aclrtStream类型指针，指定关联的流，用于维护异步操作的执行顺序。</li></ul><p>以下示例展示了核函数（Kernel）的声明与调用方式。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 声明</span>
<span class="n">__global__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom</span><span class="p">(</span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">total_length</span><span class="p">);</span>
<span class="c1">// 调用</span>
<span class="n">add_custom</span><span class="o">&lt;&lt;&lt;</span><span class="n">blocks_per_grid</span><span class="p">,</span><span class="w"> </span><span class="n">threads_per_block</span><span class="p">,</span><span class="w"> </span><span class="n">dyn_ubuf_size</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span><span class="p">(</span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="mi">1024</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const g=a(t,[["render",e]]);export{h as __pageData,g as default};
